using AVE.ElectricityBot.Services.Implementations;

namespace AVE.ElectricityBot.Tests;

/// <summary>
/// Кому пересилати пост з каналу (@dnipro_svet, @ddnepr_vse): користувачу з провайдером (301 — ДТЕК, 303 — ЦЕК) і групою.
/// Кейси взяті з реальних постів, розібраних під час налаштування фільтра
/// </summary>
public class ChannelMessageClassifierTests
{
    private static bool Matches(string text, int userDsoId, string userGroup) =>
        ChannelMessageClassifier.MatchesUser(ChannelMessageClassifier.Parse(text), userDsoId, userGroup);

    /// <summary>Група користувача рахується лише в секції його провайдера; формати груп (1.1,5.1 / емодзі-цифри)</summary>
    [Theory]
    [InlineData("ДТЕК групи 4.1,5.1,5.2 відключення до 18:00", 301, "5.1", true)]
    [InlineData("ЦЕК: 5.1 до 13:30\n5.1 ДТЕК група без змін до 17:00", 301, "5.1", true)]
    [InlineData("Споживачі ЦЕКу групи 5.1 — відновлення до 20:00", 301, "5.1", false)]
    [InlineData("ДТЕК 1.1 до 12:00, ЦЕК 5.1 з 13:00", 301, "5.1", false)]
    [InlineData("📢 Шановні споживачі! За розпорядженням НЕК \"Укренерго\"\n🔹 Черга 5.1\n17:00-19:00", 301, "5.1", false)]
    [InlineData("📢 Шановні споживачі! За розпорядженням НЕК \"Укренерго\"\n🔹 Черга 5.1\n17:00-19:00", 303, "5.1", true)]
    [InlineData("ДТЕК станом на 14:00\nДля ЦЕК дивимось тут\n1.1 12:00-19:00\n5.1 19:00-22:30", 301, "5.1", true)]
    [InlineData("ДТЕК  на 16 листопада\n1️⃣.1️⃣ черга  00:00-03:30\n5️⃣.1️⃣ черга 10:00-14:00", 301, "5.1", true)]
    [InlineData("ДТЕК  на 16 листопада\n1️⃣.1️⃣ черга  00:00-03:30\n5️⃣.2️⃣ черга 10:00-14:00", 301, "5.1", false)]
    [InlineData("Графік ДТЕК на 10.11.2026\nГрупа 5.1\n• 04:30 — 08:30", 301, "5.1", true)]
    public void GroupsAreMatchedWithinProviderSection(string text, int userDsoId, string userGroup, bool expected) =>
        Assert.Equal(expected, Matches(text, userDsoId, userGroup));

    /// <summary>Рядок «Графік ЦЕК дивимось тут» означає, що пост про іншого провайдера</summary>
    [Theory]
    [InlineData("Графік Для ЦЕК на 30 листопада\n\nДТЕК дивимось тут ❗️", 301, "5.1", false)]
    [InlineData("Графік Для ЦЕК на 30 листопада\n\nДТЕК дивимось тут ❗️", 303, "5.1", false)]
    [InlineData("Зміни для ЦЕК: з 14:00 до 18:00 відключення\n\nДТЕК дивимось тут", 303, "5.1", true)]
    [InlineData("Станом на 7:00 графіки без змін\n\nГрафік ЦЕК дивимось тут", 301, "5.1", false)]
    [InlineData("Станом на 7:00 графіки скасовано\n\nГрафік ЦЕК дивимось тут", 301, "5.1", true)]
    [InlineData("Станом на 7:00 графіки скасовано\n\nГрафік ЦЕК дивимось тут", 303, "5.1", false)]
    [InlineData("Станом на 7:00 графіки без змін\n\nГрафік ЦЕК дивимось тут", 303, "5.1", false)]
    [InlineData("Всі відключення та ввімкнення згідно графіків без змін\nГрафікі ДТЕК дивимось тут\nГрафіки ЦЕК дивимось тут", 301, "5.1", false)]
    [InlineData("Графіки скасовано до 18:00\nГрафікі ДТЕК дивимось тут\nГрафіки ЦЕК дивимось тут", 301, "5.1", true)]
    [InlineData("Графіки скасовано до 18:00\nГрафікі ДТЕК дивимось тут\nГрафіки ЦЕК дивимось тут", 303, "5.1", true)]
    [InlineData("Зараз частково з'являється світло після екстрених відключень\nТермін відновлення, що пише сайт ДТЕК, автоматичні, не дивіться туди покищо", 301, "5.1", true)]
    public void ReferenceLineSendsToOtherProvider(string text, int userDsoId, string userGroup, bool expected) =>
        Assert.Equal(expected, Matches(text, userDsoId, userGroup));

    /// <summary>Рішення Укренерго — всім; огляди, коментарі та інші регіони — нікому</summary>
    [Theory]
    [InlineData("Укренерго закликає економно споживати світло ввечері", 301, "5.1", false)]
    [InlineData("Укренерго: завтра графіки відключень не застосовуватимуться", 301, "5.1", true)]
    [InlineData("Завтра відключення світла НЕ прогнозуються, – Укренерго.", 301, "5.1", true)]
    [InlineData("💡Завтра відключатимуть світло у всіх областях, — Укренерго", 301, "5.1", true)]
    [InlineData("❗️Найскладніша ситуація з електропостачанням наразі на Дніпропетровщині та Київщині, — Укренерго\n\nЧерез російські атаки на енергооб’єкти зранку також зафіксовано знеструмлення у Вінницькій, Донецькій, Житомирській, Запорізькій, Одеській, Полтавській, Рівненській, Харківській, Хмельницькій та Чернігівській областях.", 301, "5.1", false)]
    [InlineData("💡Відключеня світла на завтра не буде, – НЕК «Укренерго».", 301, "5.1", true)]
    [InlineData("💡Графіки погодинних відключень в Україні вводяться з 15:00 і до кінця доби, – Укренерго.", 301, "5.1", true)]
    [InlineData("У Києві за командою Укренерго застосовано графіки відключень на 30 вересня", 301, "5.1", false)]
    [InlineData("💡Графіки відключень можуть діяти всю зиму, війна не закінчена, — голова «Укренерго» Зайченко", 301, "5.1", false)]
    [InlineData("⚠️Завтра, заходи обмеження електроенергії не прогнозуються.\n\nУкренерго.", 301, "5.1", true)]
    [InlineData("❗️Інформація про відключення електроенергії \n\nЗавтра, 10 листопада, у частині областей цілодобово діятимуть планові відключення електроенергії: \n\n• для промисловості  –  графіки обмеження потужності;\n\n• для всіх категорій споживачів – графіки погодинних відключень (від 2 до 4 черг).\n\nПричина – наслідки ворожих атак на енергосистему. Енергетики цілодобово відновлюють пошкоджене обладнання та мережі, щоб якнайшвидше повернути світло в оселі українців.", 301, "5.1", true)]
    [InlineData("❗️Інформація про відключення електроенергії \n\nЗавтра, 10 листопада, у частині областей цілодобово діятимуть планові відключення електроенергії: \n\n• для всіх категорій споживачів – графіки погодинних відключень (від 2 до 4 черг).", 303, "5.1", true)]
    [InlineData("Завтра у більшості регіонів будуть відключення електроенергії від 1 до 4 черг, — Укренерго", 303, "5.1", true)]
    [InlineData("Завтра у більшості регіонів будуть відключення електроенергії від 1 до 4 черг, — Укренерго", 301, "5.1", true)]
    [InlineData("За повідомленням «Укренерго» завтра, 2 липня, в період з 17:00 до 22:00 можливе застосування графіків погодинних відключень", 303, "5.1", true)]
    [InlineData("Завтра, 30 листопада, в усіх регіонах вимикатимуть світло з 00:00 до 23:59 (обсягом від 0,5 до 3 черг), — Укренерго", 303, "5.1", true)]
    [InlineData("Завтра, 29 листопада, будуть діяти стабілізаційні відключення світла з 00:00 до 23:59 обсягом від 0.5 до 2.5 черг", 301, "5.1", true)]
    [InlineData("УВАГА! ІНФОРМАЦІЯ ПРО ВІДКЛЮЧЕННЯ\n\nЗавтра, 19 ЖОВТНЯ, у кількох областях України вимушено будуть застосовуватись заходи обмеження споживання", 303, "5.1", true)]
    [InlineData("⚡ Чому в Україні повертаються графіки відключень світла?\nЧерез постійні ворожі обстріли енергосистема пошкоджена, — Укренерго", 301, "5.1", false)]
    [InlineData("😡 Сьогодні відключення світла посилюються — Укренерго\n\nНа сьогодні щойно збільшено обсяг обмежень електропостачання.", 301, "5.1", true)]
    public void UkrenergoDecisionsGoToEveryone(string text, int userDsoId, string userGroup, bool expected) =>
        Assert.Equal(expected, Matches(text, userDsoId, userGroup));

    /// <summary>Екстрені/аварійні по місту — всім; «екстрені служби/поставки» — не алерт</summary>
