        Assert.Equal(expected, Matches(text, userDsoId, userGroup));

    /// <summary>Пости про інші міста та передмістя не пересилаються; вулиці Дніпра з такими назвами — так</summary>
    [Theory]
    [InlineData("Павлоград: для споживачів ЦЕК графік на завтра, 10 листопада:\n\n📌 1 черга:\n✔️ 05:00 - 10:00;\n✔️ 15:00 - 20:00.\n\n📌 2 черга:\n✔️ 00:00 - 05:00;", 303, "1.1", false)]
    [InlineData("М.Тернівка\nДе не зявилося світло почерзі 2.2\nВедуться ремонтні роботи", 301, "2.2", false)]
    [InlineData("м.Павлоград\nз 18:30 додатково застосовується відключення підчерги 6.2 ЦЕК ❗️", 303, "6.2", false)]
    [InlineData("Групи ДТЕК 1.1 1.2 та 2.1;2.2 відключенні за графіком до 00:00\n5.1 5.2 відключені до 22:00\nОчікуємо відновлення електроенергії\nПо місту Самар та району можлива затримка", 301, "5.1", true)]
