    [InlineData("Кам'янське: група ДТЕК 5.1 — відключення до 20:00", 301, "5.1", false)]
    [InlineData("(Група 5.2) Екстрені відключення (до 20:30 23.01.2026): м. Дніпро, м. Самар", 301, "5.2", true)]
    [InlineData("м. Підгороднє, с-ще Обухівка, с-ще Слобожанське\nСвітло буде відновлено у найближчий час по групі 1.2 очікуєм", 301, "1.2", false)]
    [InlineData("Смт.Слобожанське де немає світла\nПерепідключено до 5.2 групи ДТЕК", 301, "5.2", false)]
    [InlineData("Електропостачання\n🏙с. Зоря (до 20:25 28.01.2026)\nВул.Передова\nТа інших по черзі 5.1", 301, "5.1", false)]
    [InlineData("Нагадуємо графік ДТЕК СКАСОВАНО\n\nПО М.Підгороднє частково ведуться ремонтні роботи до 17:00", 301, "5.1", true)]
    [InlineData("Група ДТЕК 5.1 відключення до 18:00, проспект Слобожанський частково", 301, "5.1", true)]
    [InlineData("Група ДТЕК 5.1: пошкодження кабелю за 200 м. від ТП, відновлення до 18:00", 301, "5.1", true)]
